import{_ as l,a0 as d,w as r,s as o,I as n,x as a,a1 as i,A as t,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 上使用 GNU Parted 对磁盘分区 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 GNU Parted 对磁盘分区 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 GNU Parted 对磁盘分区 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 GNU Parted 对磁盘分区 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20210401 Partition a drive on Linux with GNU Parted","title":"在 Linux 上使用 GNU Parted 对磁盘分区","tag":"202204","desc":""},"relativePath":"202204/20210401 Partition a drive on Linux with GNU Parted.md","filePath":"[post].md"}'),h={name:"202204/20210401 Partition a drive on Linux with GNU Parted.md"};function u(g,s,k,b,c,m){const e=d("Link");return r(),o("div",null,[s[23]||(s[23]=n("h1",{id:"在-linux-上使用-gnu-parted-对磁盘分区",tabindex:"-1"},[a("在 Linux 上使用 GNU Parted 对磁盘分区 "),n("a",{class:"header-anchor",href:"#在-linux-上使用-gnu-parted-对磁盘分区","aria-label":"Permalink to “在 Linux 上使用 GNU Parted 对磁盘分区”"},"​")],-1)),s[24]||(s[24]=n("blockquote",null,[n("p",null,"了解对新的储存设备分区的基础知识，然后下载我们的速查表，让信息近在咫尺。")],-1)),s[25]||(s[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202204/12/162040edndfpnkn8233ppd.jpg",alt:""})],-1)),s[26]||(s[26]=n("p",null,"在 21 世纪，我们往往认为数据存储是理所当然的。我们有许多存储介质，相对价格便宜，而且有许多不同的可用类型。然而，不论你获得的免费云存储空间有多少，没有比有一个物理硬盘空间来存储重要的数据更好了（或容量真的很大的，而当你又在一个慢速网络上时）。然而，没有几块硬盘买回来就是现成的，至少在理想的状况下可以直接使用的。无论你是买了一块新硬盘，还用不同分区安装一个系统，你需要知道怎么在 Linux 上为磁盘分区。",-1)),n("p",null,[s[1]||(s[1]=a("这篇文章介绍了 GNU Parted ，它磁盘分区最好的工具之一。如果你偏向使用图形化程序，而不算终端命令行，请阅读我的《",-1)),i(e,{href:"https://opensource.com/article/18/11/partition-format-drive-linux#gui"},{default:t(()=>[...s[0]||(s[0]=[a("为 Linux 格式化驱动器",-1)])]),_:1}),s[2]||(s[2]=a("》这篇文章。",-1))]),s[27]||(s[27]=p('<h3 id="磁盘标签、分区和文件系统" tabindex="-1">磁盘标签、分区和文件系统 <a class="header-anchor" href="#磁盘标签、分区和文件系统" aria-label="Permalink to “磁盘标签、分区和文件系统”">​</a></h3><p>技术上来说，一个硬盘驱动器不需要很多软件，就可用作存储设备。然而，在没有分区表和文件系统等现代惯例的情况下使用硬盘是困难的、不切实际的，而且对你的数据不安全。</p><p>关于硬盘驱动器，这里有三个你需要知道的重要概念：</p><ul><li><ruby>磁盘标签<rt>disk label</rt></ruby>（或者 <ruby>分区表<rt>partition table</rt></ruby>）是放置在磁盘驱动器起始位置的元数据，它告诉计算机可用的存储是何种类型、以及它在磁盘驱动器的位置等信息。</li><li><ruby>分区<rt>partition</rt></ruby> 是一个识别文件系统位置的边界。举个例子，如果你有一个 512GB 的硬盘，你可以用占用所有磁盘容量（512GB）分成一个分区，或者分成两个分区，每个占用 256GB ，或者分成三个分区，占用各种不同大小的空间等等。</li><li><ruby>文件系统<rt>filesystem</rt></ruby> 是一个硬盘驱动器和计算机两者约定俗成的存储方案。计算机必须知道怎样读取文件系统来拼凑存储在驱动器上的数据，并且必须知道怎样写入数据到文件系统并保持数据的完整性。</li></ul><p>GNU Parted 程序管理着前两个概念：磁盘标签和分区。Parted 对文件系统有所了解，但是它把文件系统的实现细节交给了其他类似 <code>mkfs</code> 这样的工具。</p>',5)),n("blockquote",null,[n("p",null,[s[4]||(s[4]=a("下载 ",-1)),i(e,{href:"https://opensource.com/downloads/parted-cheat-sheet"},{default:t(()=>[...s[3]||(s[3]=[a("GNU Parted 速查表",-1)])]),_:1})])]),s[28]||(s[28]=p(`<h3 id="确定磁盘驱动器的位置" tabindex="-1">确定磁盘驱动器的位置 <a class="header-anchor" href="#确定磁盘驱动器的位置" aria-label="Permalink to “确定磁盘驱动器的位置”">​</a></h3><p>使用 GNU Parted 之前，你必须确定你的驱动器在你的系统上的位置。首先，将你要格式化的磁盘驱动器连接到你的系统，然后用 <code>parted</code> 命令查看连接到你的计算机的设备：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sda print devices</span></span>
<span class="line"><span>/dev/sda (2000GB)</span></span>
<span class="line"><span>/dev/sdb (1000GB)</span></span>
<span class="line"><span>/dev/sdc (1940MB)</span></span></code></pre></div><p>你最新连接设备的名称在字母表上晚于连接时间更长的设备。举个例子，<code>/dev/sdc</code> 最有可能是我刚刚连接的磁盘。我能通过它的容量大小来确认，相比于我的工作站上的主要驱动器的 TB 大小来说，因为我知道我插入的 U 盘只有 2GB（1940MB，足够接近）大小。如果你不能确定，你可以得到的更多关于你想要分区的驱动器的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdc print</span></span>
<span class="line"><span>Model: Yoyodyne Tiny Drive 1.0 (scsi)    </span></span>
<span class="line"><span>Disk /dev/sdc: 1940MB</span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B</span></span>
<span class="line"><span>Partition Table: msdos</span></span>
<span class="line"><span>Disk Flags:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number  Start   End     Size    File system  Name  Flags</span></span>
<span class="line"><span> 1      1049kB  2048kB  1024kB  BS           Bloat  Hidden</span></span>
<span class="line"><span> 2      2049kB  1939MB  1937MB  FAT32        MyDrive</span></span></code></pre></div><p>有些驱动器比其他驱动器有更多的元数据。这个磁盘表明它的物理驱动器品牌是 Yoyodyne ，此外，在磁盘的起始处包含了一个小的隐藏分区，后面是一个兼容 Windows 的臃肿的 FAT32 分区。这确实是我要重新打算格式化的驱动器。</p><p>继续之前，<em>确认</em> 你已经确定了要分区的正确驱动器。 <em>对错误的驱动器重新分区会导致数据丢失。</em> 为了安全起见，在本文中所有具有潜在破环性的命令都指向在你的系统中不太可能有的 <code>/dev/sdX</code> 设备。</p><h3 id="创建磁盘标签-或者分区表" tabindex="-1">创建磁盘标签（或者分区表） <a class="header-anchor" href="#创建磁盘标签-或者分区表" aria-label="Permalink to “创建磁盘标签（或者分区表）”">​</a></h3><p>要在磁盘上创建一个分区，驱动器必须要有一个<ruby>磁盘标签<rt>disk label</rt></ruby>。磁盘标签也被叫做 <ruby>分区表<rt>partition table</rt></ruby>，所以 Parted 对两个术语都接受。</p><p>要创建一个磁盘卷标，使用 <code>mklabel</code> 或 <code>mktable</code> 子命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX mklabel gpt</span></span></code></pre></div><p>这个命令在 <code>/dev/sdX</code> 的驱动器前面创建了一个 <strong>gpt</strong> 标签，删除了任何可能存在的标签。这是一个快速的过程，因为所有被替换的信息都是关于分区的元数据。</p><h3 id="创建分区" tabindex="-1">创建分区 <a class="header-anchor" href="#创建分区" aria-label="Permalink to “创建分区”">​</a></h3><p>要在磁盘创建分区，使用 <code>mkpart</code> 子命令，后跟可选的分区名称，再跟分区的开始和结束位置。如果你在磁盘上只需要一个分区，那么大小调整是容易的：开始位置输入 1 ，结束位置输入 100% 。使用 <code>--align opt</code> 参数允许 Parted 调整分区边界位置便于磁盘获得最佳性能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX --align opt \\</span></span>
<span class="line"><span>mkpart example 1 100%</span></span></code></pre></div><p>用 <code>print</code> 子命令查看你的新分区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX print</span></span>
<span class="line"><span>Model: Yoyodyne Tiny Drive 1.0 (scsi)</span></span>
<span class="line"><span>Disk /dev/sdi: 1940MB</span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B</span></span>
<span class="line"><span>Partition Table: gpt</span></span>
<span class="line"><span>Disk Flags:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number  Start   End     Size  </span></span>
<span class="line"><span> 1      1049kB  1939MB  1938MB</span></span></code></pre></div><p>你不必将整个磁盘用作一个分区。分区的优势是在一个磁盘上可以存在多个文件系统，它们之间不会相互干扰。在确定分区大小的时候，你可以使用 <code>unit</code> 子命令来设置你想用的测量方法。Parted 可以理解<ruby>扇区<rt>sector</rt></ruby>、<ruby>柱面<rt>cylinder</rt></ruby>、<ruby>磁头<rt>head</rt></ruby>、<ruby>字节<rt>byte</rt></ruby>、KB、MB、GB、TB 和百分比。（LCTT 译注：具体使用方法请参阅手册页）</p><p>你也可以指定你打算使用的分区的文件系统。这并不会创建文件系统，但是它为你以后方便使用提供了元数据。</p><p>将磁盘对半分，一个是 XFS 文件系统，另一个是 EXT4 文件系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX --align opt \\</span></span>
<span class="line"><span>mkpart xfs 1 50%</span></span>
<span class="line"><span>$ parted /dev/sdX --align opt \\</span></span>
<span class="line"><span>mkpart ext4 51% 100%</span></span></code></pre></div><h3 id="命名分区" tabindex="-1">命名分区 <a class="header-anchor" href="#命名分区" aria-label="Permalink to “命名分区”">​</a></h3><p>除了标记分区用于什么文件系统之外，你也可以为每个分区命名。一些文件管理器和工具可以读取分区名称，能够帮助你区分驱动器。例如，我经常有几个不同的驱动器连接到我的媒体工作站，每个属于一个不同的项目。当创建这些驱动器的时候，我同时命名了分区和文件系统，这样，无论我怎么看我的系统，有重要数据的位置都会被清楚地标示出来。</p><p>要命名一个分区，你必须知道它的序号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX print</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Number  Start   End     Size   File system  Name     Flags</span></span>
<span class="line"><span> 1      1049kB  990MB   989MB  xfs          example</span></span>
<span class="line"><span> 2      1009MB  1939MB  930MB  ext4         noname</span></span></code></pre></div><p>要命名分区 1：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX name 1 example</span></span>
<span class="line"><span>$ parted /dev/sdX print</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Number  Start   End     Size   File system  Name     Flags</span></span>
<span class="line"><span> 1      1049kB  990MB   989MB  xfs          example</span></span>
<span class="line"><span> 2      1009MB  1939MB  930MB  ext4         noname</span></span></code></pre></div><h3 id="创建文件系统" tabindex="-1">创建文件系统 <a class="header-anchor" href="#创建文件系统" aria-label="Permalink to “创建文件系统”">​</a></h3><p>要让你的驱动器能够正常使用，你必须在新分区上创建一个文件系统。GNU Parted 并不做这些，因为它只是一个分区管理器。在磁盘上创建文件系统的 Linux 命令是 <code>mkfs</code>，但也有一些有用的工具可以让你用来创建特定类型的文件系统。例如，<code>mkfs.ext4</code> 创建 EXT4 文件系统，<code>mkfs.xfs</code> 创建 XFS 文件系统等等。</p><p>你的分区位于磁盘驱动器的“内部” ，所以你不是在 <code>/dev/sdX</code> 上创建文件系统，而是在 <code>/dev/sdX1</code> 上为第一个分区创建文件系统，在 <code>/dev/sdX2</code> 上为第二个分区创建，以此类推。</p><p>这里是一个创建 XFS 文件系统的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkfs.xfs -L mydrive /dev/sdX1</span></span></code></pre></div><h3 id="下载我们的速查表" tabindex="-1">下载我们的速查表 <a class="header-anchor" href="#下载我们的速查表" aria-label="Permalink to “下载我们的速查表”">​</a></h3><p>Parted 是一个灵活而强大的工具。你可以发出命令，如本文所示的那样，或者激活一个交互模式以不断 “连接” 你指定的驱动器:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX</span></span>
<span class="line"><span>(parted) print</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Number  Start   End     Size   File system  Name     Flags</span></span>
<span class="line"><span> 1      1049kB  990MB   989MB  xfs          example</span></span>
<span class="line"><span> 2      1009MB  1939MB  930MB  ext4         noname</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(parted) name 1 mydrive</span></span>
<span class="line"><span>(parted)</span></span></code></pre></div>`,35)),n("p",null,[s[6]||(s[6]=a("如果你打算经常使用 Parted ，",-1)),i(e,{href:"https://opensource.com/downloads/parted-cheat-sheet"},{default:t(()=>[...s[5]||(s[5]=[a("下载我们的 GNU Parted 速查表",-1)])]),_:1}),s[7]||(s[7]=a("，让信息近在咫尺。",-1))]),s[29]||(s[29]=n("hr",null,null,-1)),n("p",null,[s[9]||(s[9]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/21/4/linux-parted-cheat-sheet"},{default:t(()=>[...s[8]||(s[8]=[a("https://opensource.com/article/21/4/linux-parted-cheat-sheet",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[10]||(s[10]=[a("Seth Kenlon",-1)])]),_:1}),s[15]||(s[15]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[11]||(s[11]=[a("lujun9972",-1)])]),_:1}),s[16]||(s[16]=a(" 译者：",-1)),i(e,{href:"https://github.com/hwlife"},{default:t(()=>[...s[12]||(s[12]=[a("hwlife",-1)])]),_:1}),s[17]||(s[17]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[19]||(s[19]=[a("Linux中国",-1)])]),_:1}),s[22]||(s[22]=a(" 荣誉推出",-1))])])}const v=l(h,[["render",u]]);export{x as __pageData,v as default};
